class C {
  init() {}

  func bar() { print("bar") }
}

class D : C {
  func foo() { print("foo") }
}

func down<T : C>(_ x: C, _: T.Type) -> T {
  return x as! T
}

func up<T : C>(_ x: T) -> C {
  return x
}

func isa<T : C>(_ x: C, _: T.Type) -> Bool {
  return x is T
}

func typeof<T>(_ x: T) -> T.Type {
  return T.self
}

protocol Scrutinizable {}

extension C : Scrutinizable {}

extension Int : Scrutinizable {}

extension Scrutinizable {
  func scrutinize() -> Any.Type {
    return typeof(self)
  }
}

// CHECK: foo
down(D(), D.self).foo()
// CHECK: bar
up(D()).bar()
// CHECK: true
print(isa(D(), D.self))
// CHECK: false
print(isa(C(), D.self))
// CHECK: C
print(C().scrutinize())
// CHECK: D
print(D().scrutinize())
// CHECK: Int
print(3.scrutinize())

