  _read {
    print("read: yielding \(backingX).")
    yield backingX
    backingX += 1
  }
  _modify {
    var temp = backingX
    print("modify: current value is \(temp).")
    yield &temp
    print("modify: incoming value is \(temp).")
    if temp >= backingX {
      print("modify: accepting.")
